import json,sys,encodings.idna
out=[]
for row in json.load(sys.stdin):
 try:
  text,n=encodings.idna.IncrementalDecoder()._buffer_decode(''.join(map(chr,row['points'])),'strict',row['final']);out.append([list(map(ord,text)),n])
 except Exception as e: out.append([type(e).__name__,str(e),getattr(e,'start',None),getattr(e,'end',None)])
print(json.dumps(out))
